Object.assign(window.TEM8_DICTIONARY, {"quite":{"media":{"uk":"media/uk/quite__gb_1.mp3","us":"media/us/quite__us_1.mp3"},"oxford":{"phon":"kwaɪt","pos":"adverb","senses":[{"en":"to some degree","cn":"颇；相当；某种程度上","lab":"British English","ex":{"en":"quite good/interesting/common/difficult","cn":"相当好／有趣／普遍／困难"}},{"en":"to the greatest possible degree","cn":"完全；十分；非常；彻底","lab":"British English","ex":{"en":"quite amazing/delicious/empty/perfect","cn":"非常惊人／美味／空／完美"}},{"en":"to a great degree; very; really","cn":"在很大程度上；很；的确","lab":"North American English","ex":{"en":"I'm quite happy to wait for you here.","cn":"我非常高兴在此等候您。"}},{"en":"used to agree with somebody or show that you understand them","cn":"（表示赞同或理解）对，正是","lab":"formal","ex":{"en":"‘He's bound to feel shaken after his accident.’ ‘Quite.’","cn":"“那次事故之后，他一定是像惊弓之鸟。”“可不是。”"}}]},"collins":{"senses":[{"pos":"ADV 副词","cn":"相当;很;颇","en":"You use quite to indicate that something is the case to a fairly great extent. Quite is less emphatic than 'very' and 'extremely'.","ex":{"en":"I felt quite bitter about it at the time","cn":"当时我对这件事感到相当怨愤。"}},{"pos":"ADV 副词","cn":"(用于强调所说的话)很，非常","en":"You use quite to emphasize what you are saying.","ex":{"en":"It is quite clear that we were firing in self defence","cn":"事实很清楚，我们开枪是出于自卫。"}},{"pos":"ADV 副词","cn":"(与否定词连用，表示语气较弱或不确定)","en":"You use quite after a negative to make what you are saying weaker or less definite.","ex":{"en":"Something here is not quite right","cn":"这里有什么地方不太对劲。"}},{"pos":"PREDET 前置限定词","cn":"（用于名词词组前，表示强调）出众的，了不起的，不同寻常的","en":"You use quite in front of a noun group to emphasize that a person or thing is very impressive or unusual.","ex":{"en":"'Oh, he's quite a character,' Sean replied","cn":"“喔，他真是个了不起的人，”肖恩回答说。"}},{"pos":"ADV 副词","cn":"正是这样;确实如此","en":"You can say 'quite' to express your agreement with someone.","ex":{"en":"'And if you buy the record it's your choice isn't it.' — 'Quite'","cn":"“如果你买这张唱片，那是你的选择，不是吗？”——“可不是嘛。”"}}]},"examples":[{"en":"‘I almost think she prefers animals to people.’ ‘ Quite right too, ’ said Bill. “","cn":"我简直认为她喜爱动物胜过喜爱人。” “没错儿。”比尔说道。"},{"en":"( NAmE ) ‘You've no intention of coming back?’ ‘I'm quite sorry, but no, I have not.’ “","cn":"你不打算回来了吗？” “是的。非常抱歉，我不想回来了。”"}]},"quiz":{"oxford":{"phon":"kwɪz","pos":"noun","senses":[{"en":"a competition or game in which people try to answer questions to test their knowledge","cn":"知识竞赛；智力游戏","ex":{"en":"a general knowledge quiz","cn":"常识问答竞赛"}},{"en":"an informal test given to students","cn":"小测验","lab":"especially North American English","ex":{"en":"a reading comprehension quiz","cn":"阅读理解小测验"}},{"en":"to ask somebody a lot of questions about something in order to get information from them","cn":"盘问；查问；询问；讯问","ex":{"en":"Four men are being quizzed by police about the murder.","cn":"警察就这起谋杀案正在盘问四个男子。"},"pos":"verb"},{"en":"to give students an informal test","cn":"测验（学生）","lab":"North American English","ex":{"en":"You will be quizzed on chapter 6 tomorrow.","cn":"明天将考你们第 6 章。"},"pos":"verb"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"问答竞赛;智力竞赛","en":"A quiz is a game or competition in which someone tests your knowledge by asking you questions.","ex":{"en":"We'll have a quiz at the end of the show.","cn":"节目的最后我们要举行一次智力竞赛。"}},{"pos":"VERB 动词","cn":"询问;查问;盘问","en":"If you are quizzed by someone about something, they ask you questions about it.","ex":{"en":"He was quizzed about his income, debts and eligibility for state benefits","cn":"他被问及收入、债务以及是否有资格享受政府发放的救济金等问题。"}}]},"media":{"uk":"media/uk/quiz__gb_1.mp3","us":"media/us/quiz__us_1.mp3"},"examples":[{"en":"Four men are being quizzed by police about the murder.","cn":"警察就这宗谋杀案正在盘问四个男子。"},{"en":"We were quizzed on our views about education.","cn":"我们被征询对教育的看法。"}]},"quality":{"media":{"uk":"media/uk/quality__gb_1.mp3","us":"media/us/quality__us_1.mp3"},"oxford":{"phon":"ˈkwɒləti","pos":"noun","senses":[{"en":"the standard of something when it is compared to other things like it; how good or bad something is","cn":"质量；品质","g":"[uncountable, countable]","ex":{"en":"Improving the quality of care for nursing home residents is a priority.","cn":"提高养老院的护理水平是一个优先事项。"}},{"en":"a high standard","cn":"上乘；优质；高标准","g":"[uncountable]","ex":{"en":"We aim to provide quality at reasonable prices.","cn":"我们的宗旨是质量上乘、价格合理。"}},{"en":"a thing that is part of a person’s character, especially something good","cn":"（尤指好的）人品，素质，品德","g":"[countable]","ex":{"en":"personal qualities such as honesty and generosity","cn":"诚实、宽容等个人品质"}},{"en":"a feature of somebody/something, especially one that makes them different from somebody/something else","cn":"特征；特质；特色","g":"[countable, uncountable]","ex":{"en":"the special quality of light and shade in her paintings","cn":"她绘画中的明、暗特征"}},{"en":"a newspaper that deals seriously with issues and has a high standard of editing and comment","cn":"严肃报纸，高品质报纸（内容严谨，编辑和评论水平高）","g":"[countable]","lab":"more frequent"},{"en":"used especially by people trying to sell goods or services to say that something is of a high quality","cn":"优质的；高质量的","g":"[only before noun]","ex":{"en":"We specialize in quality furniture.","cn":"我们专营优质家具。"},"pos":"adjective"},{"en":"very good","cn":"顶呱呱；棒极了","lab":"British English, slang，，","ex":{"en":"‘What was the film like?’ ‘Quality!’","cn":"“这部电影怎么样？”“棒极了！”"},"pos":"adjective"}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"质量；品质","en":"The quality of something is how good or bad it is.","ex":{"en":"Everyone can greatly improve the quality of life","cn":"每个人都可以大大改善生活质量。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"优质;高级","en":"Something of quality is of a high standard.","ex":{"en":"...a college of quality","cn":"优秀的学院"}},{"pos":"N-COUNT 可数名词","cn":"优秀品质;品德","en":"Someone's qualities are the good characteristics that they have which are part of their nature.","ex":{"en":"Sometimes you wonder where your kids get their good qualities","cn":"有时你会想，孩子们身上的优秀品质是从何而来呢？"}},{"pos":"N-COUNT 可数名词","cn":"特征；性质;特性","en":"You can describe a particular characteristic of a person or thing as a quality .","ex":{"en":"...a childlike quality.","cn":"孩子般的天真特质"}},{"pos":"ADJ 形容词","cn":"内容严肃的报纸","en":"The quality papers or the quality press are the more serious newspapers which give detailed accounts of world events, as well as reports on business, culture, and society.","ex":{"en":"Even the quality papers agreed that it was a triumph.","cn":"即使是内容严肃的报纸也认为这是一次胜利。"}}]},"examples":[{"en":"Their quality of life improved dramatically when they moved to France.","cn":"他们移居法国以后，生活质量大大提高。"},{"en":"When costs are cut product quality suffers.","cn":"一降低成本，产品质量就会受到影响。"}]},"quit":{"media":{"uk":"media/uk/quit__gb_1.mp3","us":"media/us/quit__us_1.mp3"},"oxford":{"phon":"kwɪt","pos":"verb","senses":[{"en":"to leave your job, school, etc.","cn":"离开（工作职位、学校等）；离任；离校","g":"[intransitive, transitive]","lab":"informal","ex":{"en":"If I don't get more money I'll quit.","cn":"不给我加薪我就辞职。"}},{"en":"to stop doing something","cn":"停止；戒掉","g":"[transitive, intransitive]","lab":"especially North American English, informal，，","ex":{"en":"I've quit smoking.","cn":"我戒了烟。"}},{"en":"to leave the place where you live","cn":"离开，迁出，搬离（住处）","g":"[transitive, intransitive]","ex":{"en":"We decided it was time to quit the city.","cn":"当时我们决定，该离开城市生活了。"}},{"en":"to close a computer program or application","cn":"关闭，退出（计算机程序等）","g":"[intransitive, transitive]","ex":{"en":"I quit the app and restarted it.","cn":"我关闭应用程序，然后重启。"}}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"放弃，辞去(工作)","en":"If you quit your job, you choose to leave it.","ex":{"en":"He quit his job as an office boy in Athens","cn":"他辞去了在雅典当办公室勤杂工的工作。"}},{"pos":"VERB 动词","cn":"停止;退出;放弃","en":"If you quit an activity or quit doing something, you stop doing it.","ex":{"en":"A nicotine spray can help smokers quit the habit without putting on weight","cn":"尼古丁喷雾剂能够帮助吸烟者在不增加体重的同时戒烟。"}},{"pos":"VERB 动词","cn":"离开(某地)","en":"If you quit a place, you leave it completely and do not go back to it.","ex":{"en":"...the idea that humans might one day quit the earth to colonise other planets","cn":"人类有朝一日可能会离开地球到其他星球定居繁衍的想法"}},{"pos":"PHRASE 短语","cn":"决定结束;就此了结","en":"If you say that you are going to call it quits, you mean that you have decided to stop doing something or being involved in something.","ex":{"en":"They raised $630,000 through listener donations, and then called it quits","cn":"他们通过听众捐款的方式筹集了63万美元后宣告结束。"}}]},"examples":[{"en":"We decided it was time to quit the city.","cn":"当时我们决定，该离开城市生活了。"},{"en":"He quit the show last year because of bad health.","cn":"去年他因身体欠佳而退出了表演。"}]},"quantum":{"media":{"uk":"media/uk/quantum__gb_1.mp3","us":"media/us/quantum__us_1.mp3"},"oxford":{"phon":"ˈkwɒntəm","pos":"noun","senses":[{"en":"a very small quantity of electromagnetic energy","cn":"量子"}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"量子的","en":"In physics, quantum theory and quantum mechanics are concerned with the behaviour of atomic particles.","ex":{"en":"Both quantum mechanics and chaos theory suggest a world constantly in flux.","cn":"量子力学和混沌理论都表明世界永远处于不断变化中。"}},{"pos":"ADJ 形容词","cn":"巨变;猛增;飞跃；突飞猛进","en":"A quantum leap or quantum jump in something is a very great and sudden increase in its size, amount, or quality.","ex":{"en":"The vaccine represents a quantum leap in healthcare","cn":"这种疫苗的问世是医疗保健领域的重大突破。"}}]}},"quick":{"media":{"uk":"media/uk/quick__gb_1.mp3","us":"media/us/quick__us_1.mp3"},"oxford":{"phon":"kwɪk","pos":"adjective","senses":[{"en":"done with speed; taking or lasting a short time","cn":"快的；迅速的；短暂的","ex":{"en":"a quick look/check/search","cn":"快速的查看／检查／搜索"}},{"en":"moving or doing something fast","cn":"敏捷的；迅速的","lab":"North American English, informal，，","ex":{"en":"a quick learner","cn":"学得快的人"}},{"en":"happening very soon or without delay","cn":"迅速的；立竿见影的","g":"[only before noun]","ex":{"en":"We need to make a quick decision.","cn":"我们需要当机立断。"}},{"en":"quickly; fast","cn":"迅速地；快速地","lab":"North American English, informal，，","ex":{"en":"Come as quick as you can!","cn":"你尽快过来吧！"},"pos":"adverb"},{"en":"doing the thing mentioned quickly","cn":"…敏捷的；…迅速的","ex":{"en":"quick-thinking","cn":"才思敏捷的"},"pos":"adverb"},{"en":"the soft, sensitive area under your nails","cn":"（指甲下的）活肉","ex":{"en":"She has bitten her nails down to the quick.","cn":"她咬指甲都咬到了活肉。"},"pos":"noun"}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"快的;迅速的;急速的","en":"Someone or something that is quick moves or does things with great speed.","ex":{"en":"You'll have to be quick. The flight leaves in about three hours","cn":"你得快点了，飞机大约3小时后起飞。"}},{"pos":"ADV-GRADED 副词","cn":"(quicker 有时表示“以更快的速度”，quickest表示“以最快的速度”，quick有时表示“以很快的速度”，但有些人认为这种用法并不规范)","en":"Quicker is sometimes used to mean 'at a greater speed', and quickest to mean 'at the greatest speed'. Quick is sometimes used to mean 'with great speed'. Some people consider this to be non-standard.","ex":{"en":"Warm the sugar slightly first to make it dissolve quicker","cn":"先将糖稍稍加热，以使其溶解得更快些。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"短暂的;持续时间很短的","en":"Something that is quick takes or lasts only a short time.","ex":{"en":"He took one last quick look about the room","cn":"他朝房间匆匆扫了最后一眼。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"立刻发生的;很快发生的","en":"Quick means happening without delay or with very little delay.","ex":{"en":"Officials played down any hope for a quick end to the bloodshed","cn":"官员们让迅速结束这场流血冲突的希望变得渺茫起来。"}},{"pos":"ADV-GRADED 副词","cn":"迅速发生地;很快发生地","en":"Quick is sometimes used to mean 'with very little delay'.","ex":{"en":"I got away as quick as I could","cn":"我尽快离开了。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"立刻的;马上的","en":"If you are quick to do something, you do not hesitate to do it.","ex":{"en":"Mark says the ideas are Katie's own, and is quick to praise her talent","cn":"马克说这些都是凯蒂自己的想法，并随即称赞起她的天赋来。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"性情急躁的;容易发怒的","en":"If someone has a quick temper, they are easily made angry."},{"pos":"PHRASE 短语","cn":"咬到了指甲肉；咬秃指甲","en":"If someone bites their nails to the quick, they bite off all the white part at the end of each nail.","ex":{"en":"Her fingernails are bitten to the quick.","cn":"她的手指甲都被咬秃了。"}},{"pos":"PHRASE 短语","cn":"触及（…）痛处;极大伤害；令…伤透了心","en":"If something cuts you to the quick, it makes you feel very upset.","ex":{"en":"I once heard her weeping in her bedroom, which cut me to the quick.","cn":"有一次，我听见她在卧室里哭泣，这深深地刺痛了我的心。"}},{"pos":"","cn":"","en":"quick as a flash→see: ; quick off the mark→see: ; quick on the uptake→see: ;"}]},"examples":[{"en":"Read our quick-and-dirty guide to creating a website.","cn":"阅读一下我们的建立网站便捷指南。"},{"en":"Come on! Quick! They’ll see us!","cn":"快点吧！快！他们会看见我们的！"}]},"quizzes":{"lemma":"quiz"},"queen":{"media":{"uk":"media/uk/queen__gb_1.mp3","us":"media/us/queen__us_1.mp3"},"oxford":{"phon":"kwiːn","pos":"noun","senses":[{"en":"the female ruler of an independent state that has a royal family","cn":"女王；女酋长；女首领","sc":"female ruler","ex":{"en":"She was crowned queen at the age of fifteen.","cn":"她 15 岁时接受加冕成为女王。"}},{"en":"the wife of a king","cn":"王后","sc":"female ruler","ex":{"en":"Henry VII and his queen, Elizabeth of York","cn":"亨利七世和王后约克的伊丽莎白"}},{"en":"a woman, place or thing that is thought to be one of the best in a particular group or area","cn":"（某领域的）杰出女性，精髓，精华","sc":"best in group","ex":{"en":"the queen of fashion","cn":"时尚女王"}},{"en":"a woman or girl chosen to perform official duties at a festival or celebration","cn":"（节日或庆典活动中）当选行使庆典职责的女子","sc":"at festival","ex":{"en":"a carnival queen","cn":"狂欢节小姐"}},{"en":"the most powerful piece used in the game of chess that can move any number of squares in any direction","cn":"后","sc":"in chess"},{"en":"a playing card with the picture of a queen on it","cn":"王后（牌）","sc":"in cards"},{"en":"a large female insect that lays eggs for the whole group","cn":"（为群体产卵的）雌性昆虫，王，后","sc":"insect","ex":{"en":"a queen bee","cn":"蜂王"}},{"en":"an offensive word for a gay man who behaves like a woman","cn":"“王后”，假娘儿们（对女性化的男同性恋者的贬称）","lab":"taboo, offensive, slang，，，，","sc":"gay"},{"en":"a successful British pop group formed in 1971. Its singer was Freddie Mercury and its albums A Night at the Opera (1975), The Game (1980) and Innuendo (1991) as well as the song Bohemian Rhapsody (1975) were all No. 1 in Britain. The 2002 musical We Will Rock You is based on the group's music.","cn":"提供同犯的罪证，揭发其他案犯（以减轻所受惩罚）","pos":""}]},"collins":{"senses":[{"pos":"N-TITLE; N-COUNT 头衔名词；可数名词","cn":"女王;女皇","en":"A queen is a woman who rules a country as its monarch.","ex":{"en":"...Queen Victoria","cn":"维多利亚女王"}},{"pos":"N-TITLE; N-COUNT 头衔名词；可数名词","cn":"皇后；王后","en":"A queen is a woman who is married to a king.","ex":{"en":"The king and queen had fled.","cn":"国王和王后都逃之夭夭了。"}},{"pos":"N-COUNT 可数名词","cn":"(某一活动的)女王，出众的女子","en":"If you refer to a woman as the queen of a particular activity, you mean that she is well-known for being very good at it.","ex":{"en":"...the queen of crime writing.","cn":"犯罪小说女王"}},{"pos":"N-COUNT 可数名词","cn":"(女性化的)同性恋男子","en":"A queen is a male homosexual who dresses and speaks rather like a woman."},{"pos":"N-COUNT 可数名词","cn":"(国际象棋中的)后","en":"In chess, the queen is the most powerful piece. It can be moved in any direction."},{"pos":"N-COUNT 可数名词","cn":"(纸牌中的)王后(牌)，Q（牌）","en":"A queen is a playing card with a picture of a queen on it.","ex":{"en":"...the queen of spades.","cn":"黑桃王后"}},{"pos":"N-COUNT 可数名词","cn":"蜂王","en":"A queen or a queen bee is a large female bee which can lay eggs."}]},"examples":[{"en":"a May queen (= at a festival to celebrate the coming of spring)","cn":"五朔节王后"},{"en":"Venice, queen of the Adriatic","cn":"威尼斯，亚得里亚海的明珠"}]},"quoting":{"lemma":"quote"},"qualifications":{"lemma":"qualification"},"quantity":{"oxford":{"phon":"ˈkwɒntəti","pos":"noun","senses":[{"en":"an amount or a number of something","cn":"数量；数额；数目","g":"[countable, uncountable]","ex":{"en":"a large/small quantity of something","cn":"大量／少量的某物"}},{"en":"the measurement of something by saying how much of it there is","cn":"量；数量","g":"[uncountable]","ex":{"en":"The data is limited in terms of both quality and quantity.","cn":"这份资料在质量和数量上都很有限。"}},{"en":"a large amount or number of something","cn":"大量；大批；众多；大宗","g":"[countable, uncountable]","ex":{"en":"The police found a quantity of drugs at his home.","cn":"警察在他家发现了大量毒品。"}}]},"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"数量;量","en":"A quantity is an amount that you can measure or count.","ex":{"en":"...a small quantity of water.","cn":"少量的水"}},{"pos":"N-UNCOUNT 不可数名词","cn":"大量;大宗；大批","en":"Things that are produced or available in quantity are produced or available in large amounts.","ex":{"en":"After some initial problems, acetone was successfully produced in quantity","cn":"解决了最初的一些问题之后，终于成功地制造出了大量丙酮。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"(尤指和质量相对的)数量","en":"You can use quantity to refer to the amount of something that there is, especially when you want to contrast it with its quality.","ex":{"en":"...the less discerning drinker who prefers quantity to quality","cn":"不求质、但求量的不那么识货的饮酒者"}},{"pos":"PHRASE 短语","cn":"未知量;未知数","en":"If you say that someone or something is an unknown quantity, you mean that not much is known about what they are like or how they will behave.","ex":{"en":"He is an unknown quantity for his rivals.","cn":"对于对手们而言，他是个未知数。"}}]},"media":{"uk":"media/uk/quantity__gb_1.mp3","us":"media/us/quantity__us_1.mp3"},"examples":[{"en":"I was overwhelmed by the sheer quantity of information available.","cn":"单是已有的信息量就大得令我不知所措。"},{"en":"The data is limited in terms of both quality and quantity.","cn":"这份资料在质量和数量上都很有限。"}]},"quiet":{"media":{"uk":"media/uk/quiet__gb_1.mp3","us":"media/us/quiet__us_1.mp3"},"oxford":{"phon":"ˈkwaɪət","pos":"adjective","senses":[{"en":"making very little noise","cn":"轻声的；轻柔的；安静的","ex":{"en":"her quiet voice","cn":"她那轻柔的声音"}},{"en":"without many people or much noise or activity","cn":"僻静的；寂静的；清静的","ex":{"en":"a quiet street/town","cn":"寂静的街道／城镇"}},{"en":"peaceful; without being interrupted","cn":"平静的；不受干扰的","ex":{"en":"to have a quiet drink","cn":"悠闲地饮酒"}},{"en":"tending not to talk very much","cn":"寡言少语的；文静的","ex":{"en":"She was quiet and shy.","cn":"她文静而又腼腆。"}},{"en":"definite but not expressed in an obvious way","cn":"克制的；稳重的；不张扬的","ex":{"en":"He had an air of quiet authority.","cn":"他神态威严稳重。"}},{"en":"the state of being calm and without much noise","cn":"宁静；寂静；平静；安静","ex":{"en":"the quiet of his own room","cn":"他自己房间的宁静"},"pos":"noun"},{"en":"to become calmer or less noisy; to make somebody/something calmer or less noisy","cn":"（使）安静下来，平静些","ex":{"en":"The demonstrators quieted down when the police arrived.","cn":"警察一到，示威者便安静了下来。"},"pos":"verb"}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"轻声的;安静的；静悄悄的","en":"Someone or something that is quiet makes only a small amount of noise.","ex":{"en":"Tania kept the children reasonably quiet and contented","cn":"塔妮娅把孩子们哄得安安静静而又心满意足。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"(地方)寂静的，安静的，清静的","en":"If a place is quiet, there is very little noise there.","ex":{"en":"She was received in a small, quiet office","cn":"她在一个安静的小办公室里受到接待。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"(地方、环境、时光)安宁的，清静的，平静的，宁静的","en":"If a place, situation, or time is quiet, there is no excitement, activity, or trouble.","ex":{"en":"...a quiet rural backwater","cn":"平静而与世隔绝的农村地区"}},{"pos":"N-UNCOUNT 不可数名词","cn":"安静;静谧","en":"Quiet is silence.","ex":{"en":"He called for quiet and announced that the next song was in our honor","cn":"他叫大家安静，然后宣布下一首歌要送给我们。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"沉默的；不出声的;一言不发的","en":"If you are quiet, you are not saying anything.","ex":{"en":"I told them to be quiet and go to sleep","cn":"我叫他们不要说话，马上睡觉。"}},{"pos":"ADJ 形容词","cn":"(感情)不外露的，不张扬的，内敛的，含蓄的","en":"If you refer, for example, to someone's quiet confidence or quiet despair, you mean that they do not say much about the way they are feeling.","ex":{"en":"He has a quiet confidence in his ability","cn":"他对自己胸有成竹，但却并不张扬。"}},{"pos":"ADJ 形容词","cn":"暗中的;秘密的;私下的","en":"You describe activities as quiet when they happen in secret or in such a way that people do not notice them.","ex":{"en":"The Swedes had sought his freedom through quiet diplomacy","cn":"瑞典人通过秘密的外交手段来争取他的自由。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"温和的;文静的;不易激动(或动怒)的","en":"A quiet person behaves in a calm way and is not easily made angry or upset.","ex":{"en":"He's a nice quiet man.","cn":"他是一个温和友善的人。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"(颜色、服饰)素净的，朴素大方的","en":"You describe colours or clothes as quiet when they are not bright or not very noticeable.","ex":{"en":"They dress in quiet colors so as not to call attention to themselves.","cn":"为了避免别人注目，他们穿得很朴素。"}},{"pos":"V-ERG 及物/不及物动词","cn":"(使)安静;(使)平静下来","en":"If someone or something quiets or if you quiet them, they become less noisy, less active, or silent.","ex":{"en":"The wind dropped and the sea quieted","cn":"风势减弱了，海面平静下来。"}},{"pos":"VERB 动词","cn":"消除，减轻(恐惧);平息(抱怨)","en":"To quiet fears or complaints means to persuade people that there is no good reason for them.","ex":{"en":"Music seemed to quiet her anxiety and loneliness.","cn":"音乐似乎能够减轻她的焦虑和孤独。"}},{"pos":"PHRASE 短语","cn":"(不抗议、不抱怨地)安静离开","en":"If someone does not go quietly, they do not leave a particular job or a place without complaining or resisting.","ex":{"en":"She's not going to go quietly.","cn":"她不会乖乖离开的。"}},{"pos":"PHRASE 短语","cn":"将…保密;保守…的秘密","en":"If you keep quiet about something or keep something quiet, you do not say anything about it.","ex":{"en":"I told her to keep quiet about it","cn":"我告诉她此事要保密。"}},{"pos":"PHRASE 短语","cn":"在暗中;秘密地；私下里","en":"If something is done on the quiet, it is done secretly or in such a way that people do not notice it.","ex":{"en":"She'd promised to give him driving lessons, on the quiet, when no one could see.","cn":"她已经保证要在别人看不见的时候私下教他开车。"}},{"pos":"","cn":"","en":"相关词组：quiet down"}]},"examples":[{"en":"I've decided to resign but I'd rather you kept quiet about it.","cn":"我已决定辞职，但希望你不要声张出去。"},{"en":"Could you keep the kids quiet while I'm on the phone?","cn":"我在打电话，你让孩子们安静点好吗？"}]},"quietly":{"oxford":{"phon":"ˈkwaɪətli","pos":"adverb","senses":[{"en":"in a way that makes very little noise","cn":"轻声地；轻柔地；安静地","ex":{"en":"to ask/speak/talk quietly","cn":"轻声地问／说／讲话"}},{"en":"in a peaceful way; without being interrupted","cn":"平静地；不被打扰地","ex":{"en":"I spent a few hours quietly relaxing.","cn":"我安静地休息了几个小时。"}},{"en":"without many people or much noise or activity","cn":"僻静地；寂静地；清静地","ex":{"en":"Sometimes a business begins quietly, as a hobby maybe, in a spare bedroom.","cn":"在空卧室里培养出的兴趣，说不定会静静演变成一门生意。"}},{"en":"in a definite, but not obvious, way","cn":"克制地；稳重地；不张扬地","ex":{"en":"He is quietly confident that they can succeed (= he is confident, but he is not talking about it too much).","cn":"他心里相信他们能成功。"}}]},"media":{"uk":"media/uk/quietly__gb_1.mp3","us":"media/us/quietly__us_1.mp3"},"examples":[{"en":"I spent a few hours quietly relaxing.","cn":"我怡然自得地轻松了几个小时。"},{"en":"He is quietly confident that they can succeed (= he is confident, but he is not talking about it too much).","cn":"他心里相信他们能成功。"}]},"quantities":{"lemma":"quantity"},"question":{"media":{"uk":"media/uk/question__gb_1.mp3","us":"media/us/question__us_1.mp3"},"oxford":{"phon":"ˈkwestʃən","pos":"noun","senses":[{"en":"a sentence, phrase or word that asks for information","cn":"问题；疑问","g":"[countable]","lab":"formal","ex":{"en":"You didn't answer my question.","cn":"你没有回答我的问题。"}},{"en":"a task or request for information that is intended to test your knowledge or understanding, for example in an exam or a competition","cn":"考题；试题","g":"[countable]","ex":{"en":"Question 3 was very difficult.","cn":"第 3 题难极了。"}},{"en":"a matter or topic that needs to be discussed or dealt with","cn":"（待讨论或处理的）事情，议题，课题","g":"[countable]","ex":{"en":"This is an issue that raises many important questions.","cn":"这事引出了许多重要的问题。"}},{"en":"doubt or not being certain about something","cn":"怀疑；困惑","g":"[uncountable, countable]","ex":{"en":"His suitability for the job is open to question.","cn":"他是否适合担任这工作还需要考虑。"}},{"en":"to ask somebody questions about something, especially officially","cn":"正式提问；质询；问","g":"[often passive]","ex":{"en":"Police are keen to question any witnesses.","cn":"警方热衷于询问任何证人。"},"pos":"verb"},{"en":"to have or express doubts about something","cn":"表示疑问；怀疑","ex":{"en":"I just accepted what he told me. I never thought to question it.","cn":"他说什么我就相信什么。我从未想过要去怀疑。"},"pos":"verb"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"问题；疑问","en":"A question is something that you say or write in order to ask a person about something.","ex":{"en":"They asked a great many questions about England","cn":"他们问了一大堆有关英格兰的问题。"}},{"pos":"VERB 动词","cn":"向…提出问题;询问;盘问","en":"If you question someone, you ask them a lot of questions about something.","ex":{"en":"This led the therapist to question Jim about his parents and their marriage","cn":"这让治疗专家问起了吉姆有关他父母及他们婚姻的情况。"}},{"pos":"VERB 动词","cn":"对…表示怀疑;对…有疑问","en":"If you question something, you have or express doubts about whether it is true, reasonable, or worthwhile.","ex":{"en":"It never occurs to them to question the doctor's decisions","cn":"他们从未想过要怀疑医生的决定。"}},{"pos":"N-SING 单数名词","cn":"疑问;怀疑;不确定","en":"If you say that there is some question about something, you mean that there is doubt or uncertainty about it. If something is in question or has been called into question, doubt or uncertainty has been expressed about it.","ex":{"en":"There's no question about their success","cn":"他们一定会成功。"}},{"pos":"N-COUNT 可数名词","cn":"(需要考虑的)问题","en":"A question is a problem, matter, or point which needs to be considered.","ex":{"en":"But the whole question of aid is a tricky political one","cn":"但是整个援助问题是个非常复杂的政治问题。"}},{"pos":"N-COUNT 可数名词","cn":"试题;考题","en":"The questions in an examination are the problems which are set in order to test your knowledge or ability.","ex":{"en":"He'd heard somewhere that the questions in economics examination papers stayed the same from year to year","cn":"他从某处听说经济学考试的考题年年都一样。"}},{"pos":"CONVENTION 惯用语","cn":"问得好，问得真有水平(用于问题难以回答、不便回答或不知道答案时)","en":"If you say 'Good question' in reply to a question, you mean that it is a difficult question to answer, or perhaps that you are embarrassed about the answer or do not know the answer.","ex":{"en":"'Why didn't you appoint Ron twelve months ago?'—'Good question.'","cn":"“你为什么12个月前不任命罗恩呢？”——“问得好。”"}},{"pos":"PHRASE 短语","cn":"被提及的;讨论中的;相关的","en":"The person, thing, or time in question is one which you have just been talking about or which is relevant.","ex":{"en":"The player in question is Mark Williams","cn":"我们所说的那个选手是马克·威廉斯。"}},{"pos":"PHRASE 短语","cn":"不可能;办不到;无法接受","en":"If you say that something is out of the question, you are emphasizing that it is completely impossible or unacceptable.","ex":{"en":"For the homeless, private medical care is simply out of the question","cn":"对于无家可归的人而言，私人医疗纯粹是天方夜谭。"}},{"pos":"PHRASE 短语","cn":"求婚","en":"If you pop the question, you ask someone to marry you.","ex":{"en":"Stuart got serious quickly and popped the question six months later.","cn":"斯图尔特很快认真起来，6个月之后便求婚了。"}},{"pos":"PHRASE 短语","cn":"（表示强调）是不可能的","en":"If you say there is no question of something happening, you are emphasizing that it is not going to happen.","ex":{"en":"As far as he was concerned there was no question of betraying his own comrades","cn":"就他而言，背叛自己的同志是不可能的。"}},{"pos":"PHRASE 短语","cn":"毫无疑问地;毫无异议地","en":"If you do something without question, you do it without arguing or asking why it is necessary.","ex":{"en":"...military formations, carrying out without question the battle orders of superior officers.","cn":"毫无异议地执行上级军官的战斗命令的部队编队"}},{"pos":"PHRASE 短语","cn":"毫无疑问(表示强调自己的观点)","en":"You use without question to emphasize the opinion you are expressing.","ex":{"en":"He was our greatest storyteller, without question.","cn":"毫无疑问，他是我们最会讲故事的人。"}}]},"examples":[{"en":"In an interview try to ask open questions that don't just need ‘Yes’ or ‘No’ as an answer.","cn":"在面试中要尽量问易于发挥的问题，不要让对方回答“是”或“否”便了事。"},{"en":"The key question of what caused the leak remains unanswered.","cn":"泄漏究竟是怎么造成的，这一关键问题仍未得到答案。"}]},"questioning":{"media":{"uk":"media/uk/questioning__gb_1.mp3","us":"media/us/questioning__us_1.mp3"},"oxford":{"phon":"ˈkwestʃənɪŋ","pos":"noun","senses":[{"en":"the activity of asking somebody questions","cn":"提问；询问；盘问","ex":{"en":"He was taken to the police station for questioning.","cn":"他被带到警察局盘问。"}},{"en":"showing that you need information, or that you have doubts","cn":"询问的；表示怀疑的","ex":{"en":"a questioning look","cn":"怀疑的目光"},"pos":"adjective"},{"en":"in the process of discovering your sexuality, gender identity or gender expression","cn":"在发现你的性取向、性别认同或性别表达的过程中","pos":"adjective"}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"(表情)询问的，探询的","en":"If someone has a questioning expression on their face, they look as if they want to know the answer to a question.","ex":{"en":"He raised a questioning eyebrow.","cn":"他探询地挑起了眉毛。"}}]},"examples":[{"en":"They faced some hostile questioning over the cost of the project.","cn":"关于这个项目的费用，他们面临着咄咄逼人的盘问。"},{"en":"He was taken to the police station for questioning.","cn":"他被带到警察局盘问。"}],"base":"question"},"quotient":{"oxford":{"phon":"ˈkwəʊʃnt","pos":"noun","senses":[{"en":"a number which is the result when one number is divided by another","cn":"商（除法所得的结果）"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"程度;系数","en":"Quotient is used when indicating the presence or degree of a characteristic in someone or something. intelligence quotient→see: ;","ex":{"en":"Being rich doesn't actually increase your happiness quotient","cn":"有钱不见得能提高你的幸福指数。"}}]},"media":{"uk":"media/uk/quotient__gb_1.mp3","us":"media/us/quotient__us_1.mp3"},"examples":[{"en":"Is all this healthy food supposed to increase my happiness quotient?","cn":"所有这些健康食品能提高我的幸福指数吗？"}]},"qualified":{"media":{"uk":"media/uk/qualified__gb_1.mp3","us":"media/us/qualified__us_1.mp3"},"oxford":{"phon":"ˈkwɒlɪfaɪd","pos":"adjective","senses":[{"en":"having passed the exams or completed the training that are necessary in order to do a particular job; having the experience to do a particular job","cn":"具备…的学历（或资历）","ex":{"en":"a qualified teacher","cn":"合格的教师"}},{"en":"having the practical knowledge or skills to do something","cn":"具备…的知识（或技能）；符合资格","g":"[not before noun]","ex":{"en":"I don't know much about it, so I don't feel qualified to comment.","cn":"关于此事我所知不多，所以觉得没资格评论。"}},{"en":"limited in some way","cn":"有限度的；有保留的；有条件的","g":"[usually before noun]","ex":{"en":"The plan was given only qualified support.","cn":"这项计划只得到有限度的支持。"}}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"(通过考试)取得资格的，有资格的，合格的","en":"Someone who is qualified has passed the examinations that they need to pass in order to work in a particular profession.","ex":{"en":"Demand has far outstripped supply of qualified teachers","cn":"有教学资格的教师远远供不应求。"}},{"pos":"ADJ 形容词","cn":"（支持、赞同）有限度的，有保留的","en":"If you give someone or something qualified support or approval, your support or approval is not total because you have some doubts.","ex":{"en":"The government has given qualified support to the idea","cn":"政府已有所保留地支持这个观点。"}},{"pos":"PHRASE 短语","cn":"有限的成功;部分成功","en":"If you describe something as a qualified success, you mean that it is only partly successful.","ex":{"en":"Even as a humanitarian mission it has been only a qualified success.","cn":"即便是作为一次人道主义行动，它也不过是取得了有限的成功。"}}]},"examples":[{"en":"I don't know much about it, so I don't feel qualified to comment.","cn":"关于此事我所知不多，所以觉得没资格评论。"},{"en":"She's extremely well qualified for the job.","cn":"她完全符合担任这项工作的条件。"}],"base":"qualify"},"quickly":{"media":{"uk":"media/uk/quickly__gb_1.mp3","us":"media/us/quickly__us_1.mp3"},"oxford":{"phon":"ˈkwɪkli","pos":"adverb","senses":[{"en":"fast","cn":"迅速地；很快地","ex":{"en":"She walked quickly away.","cn":"她迅速走开了。"}},{"en":"soon; after a short time","cn":"不久；立即","ex":{"en":"to act/respond quickly","cn":"行动／反应迅速"}}]},"examples":[{"en":"It quickly became clear that she was dying.","cn":"很快就看得出她当时已生命垂危。"},{"en":"The last few weeks have gone quickly (= the time seems to have passed quickly).","cn":"最近的几个星期过得很快。"}]},"qualification":{"oxford":{"phon":"ˌkwɒlɪfɪˈkeɪʃn","pos":"noun","senses":[{"en":"an exam that you have passed or a course of study that you have successfully completed","cn":"（通过考试或学习课程取得的）资格，学历","g":"[countable, usually plural]","lab":"British English","ex":{"en":"academic/educational/professional/vocational qualifications","cn":"学术／教育／专业／职业资历"}},{"en":"a skill or type of experience that you need for a particular job or activity","cn":"（通过经验或具备技能而取得的）资格，资历","g":"[countable]","ex":{"en":"What qualifications do radio presenters require?","cn":"电台主持人需要什么资格？"}},{"en":"information that you add to a statement to limit the effect that it has or the way it is applied","cn":"限定条件","g":"[countable, uncountable]","ex":{"en":"I accept his theories, but not without certain qualifications.","cn":"我接受他的理论，但并非毫无保留。"}},{"en":"the fact of passing an exam, completing a course of training or reaching the standard necessary to do a job or take part in a competition","cn":"获得资格；合格；达到标准","g":"[uncountable]","ex":{"en":"Nurses in training should be given a guarantee of employment following qualification.","cn":"接受培训的护士取得资格后应有工作保障。"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"(通过考试获得的)资格，学历;资格考试","en":"Your qualifications are the examinations that you have passed.","ex":{"en":"They will be encouraged to mix academic A-levels with vocational qualifications","cn":"将鼓励他们在取得优秀学习成绩的同时也要获得一定的职业资质。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"(通过考试后)取得资格，合格，达到标准","en":"Qualification is the act of passing the examinations you need to work in a particular profession.","ex":{"en":"Following qualification, he worked as a social worker.","cn":"通过资格考试认证之后，他做了一名社会工作者。"}},{"pos":"N-COUNT 可数名词","cn":"（完成某项活动或任务所需的）素质，技能，资历","en":"The qualifications you need for an activity or task are the qualities and skills that you need to be able to do it.","ex":{"en":"Responsibility and reliability are necessary qualifications","cn":"有责任感、值得信赖是必备的素质。"}},{"pos":"N-VAR 可变名词","cn":"限制条件;限定事项","en":"A qualification is a detail or explanation that you add to a statement to make it less strong or less general.","ex":{"en":"The empirical evidence considered here is subject to many qualifications","cn":"此处提及的实验证据有诸多限制条件。"}}]},"media":{"uk":"media/uk/qualification__gb_1.mp3","us":"media/us/qualification__us_1.mp3"},"examples":[{"en":"A victory in this game will earn them qualification for the World Cup.","cn":"这场比赛的胜利将使他们取得世界杯的参赛资格。"},{"en":"Previous teaching experience is a necessary qualification for this job.","cn":"过往的教学经验是担任这项工作的必备条件。"}]},"quietness":{"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"not making a loud sound","cn":""},{"en":"quiet – especially because you do not want people to hear or be disturbed","cn":""}]},"examples":[{"en":"We’ll have to be quiet so as not to wake the baby.","cn":"","src":"ld"},{"en":"It’s a nice car. The engine’s really quiet.","cn":"","src":"ld"}],"media":{"uk":"media/uk/quietness__gb_1.mp3","us":"media/us/quietness__us_1.mp3"},"oxford":{"phon":"ˈkwaɪətnəs","pos":"noun","senses":[{"en":"the state of having very little noise","cn":"轻声的；轻柔的；安静的","ex":{"en":"the quietness of the countryside","cn":"乡村的宁静"}},{"en":"the state of not talking very much; the quality of tending to not talk very much","cn":"寡言少语的；文静的","ex":{"en":"His quietness worried her.","cn":"他的沉默不语令她不安。"}},{"en":"the state of not having many people or much noise or activity","cn":"僻静的；寂静的；清静的","ex":{"en":"the relative quietness in the art market","cn":"艺术市场相对平静"}}]}},"quoted":{"lemma":"quote"},"quotes":{"lemma":"quote"},"queue":{"media":{"uk":"media/uk/queue__gb_1.mp3","us":"media/us/queue__us_1.mp3"},"oxford":{"phon":"kjuː","pos":"noun","senses":[{"en":"a line of people, cars, etc. waiting for something or to do something","cn":"（人、汽车等的）队，行列","lab":"British English","ex":{"en":"There were long queues at polling stations.","cn":"投票站排着长队。"}},{"en":"a list of items of data stored in a particular order","cn":"（存储的数据）队列","lab":"computing"},{"en":"to wait in a line of people, vehicles, etc. in order to do something, get something or go somewhere","cn":"（人、车等）排队等候","g":"[intransitive]","lab":"British English","ex":{"en":"People queued up outside.","cn":"人们在外面排起了队。"},"pos":"verb"},{"en":"to add tasks to other tasks so that they are ready to be done in order; to come together to be done in order","cn":"（使）排队；列队等待","g":"[transitive, intransitive]","lab":"computing","ex":{"en":"The system queues the jobs before they are processed.","cn":"这系统先把任务排队再进行处理。"},"pos":"verb"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"(等候的)一列人，一队车辆","en":"A queue is a line of people or vehicles that are waiting for something.","ex":{"en":"I watched as he got a tray and joined the queue","cn":"我看着他拿了个托盘排起了队。"}},{"pos":"N-COUNT 可数名词","cn":"(为得到某机会而等待的)长列，长队","en":"If you say there is a queue of people who want to do or have something, you mean that a lot of people are waiting for an opportunity to do it or have it.","ex":{"en":"Manchester United would be at the front of a queue of potential buyers","cn":"在众多潜在的买家中，曼彻斯特联队将排在最前列。"}},{"pos":"VERB 动词","cn":"排队(等候)","en":"When people queue, they stand in a line waiting for something.","ex":{"en":"I had to queue for quite a while.","cn":"我不得不排一会儿队。"}},{"pos":"N-COUNT 可数名词","cn":"队列(指等待计算机处理的任务列表)","en":"A queue is a list of computer tasks which will be done in order.","ex":{"en":"Your print job has been sent to the network print queue.","cn":"你的打印任务已经发送到了网络打印列表中。"}},{"pos":"VERB 动词","cn":"使(待处理任务)成队列","en":"To queue a number of computer tasks means to arrange them to be done in order."},{"pos":"","cn":"","en":"相关词组：queue up"}]},"examples":[{"en":"Italian football clubs are queuing up to sign the young star.","cn":"意大利的足球俱乐部都抢着要与这个年轻球星签约。"},{"en":"The system queues the jobs before they are processed.","cn":"这系统先把任务排列再进行处理。"}]},"quarter":{"media":{"uk":"media/uk/quarter__gb_1.mp3","us":"media/us/quarter__us_1.mp3"},"oxford":{"phon":"ˈkwɔːtə(r)","pos":"noun","senses":[{"en":"one of four equal parts of something","cn":"四等份之一","g":"[countable]","lab":"especially in North American English","sc":"1 of 4 parts","ex":{"en":"a quarter of an hour/a century","cn":"一刻钟；四分之一世纪"}},{"en":"a period of 15 minutes either before or after every hour","cn":"（正点之前或之后的）15 分钟，一刻钟","g":"[countable]","lab":"North American English also","sc":"15 minutes","ex":{"en":"It’s (a) quarter to four now—I’ll meet you at (a) quarter past.","cn":"现在是差一刻四点，我会在四点一刻和你碰面。"}},{"en":"a period of three months, used especially as a period for which bills are paid or a company’s income is calculated","cn":"三个月时间；季度；季","g":"[countable]","sc":"3 months","ex":{"en":"The rent is due at the end of each quarter.","cn":"租金于每季度末缴纳。"}},{"en":"a district or part of a town","cn":"城镇的区（或一部分）","g":"[countable, usually singular]","sc":"part of town","ex":{"en":"the historic quarter of the city","cn":"这座城市具有历史意义的城区"}},{"en":"a person or group of people, especially as a source of help, information or a reaction","cn":"（尤指能提供帮助、信息或作出反应的）个人，群体","g":"[countable]","sc":"person/group","ex":{"en":"Support for the plan came from an unexpected quarter.","cn":"支持这一计划的是没料想到的一方。"}},{"en":"a coin of the US and Canada worth 25 cents","cn":"（美国和加拿大的）25 分硬币","g":"[countable]","sc":"25 cents"},{"en":"rooms that are provided for soldiers, servants, etc. to live in","cn":"（供士兵、服务人员等居住的）营房，宿舍，住房","g":"[plural]","sc":"rooms to live in","ex":{"en":"We were moved to more comfortable living quarters.","cn":"我们搬进了较舒适的住处。"}},{"en":"the period of time twice a month when we can see a quarter of the moon","cn":"半圆的月相；上弦（或下弦）月","g":"[countable]","sc":"of moon","ex":{"en":"The moon is in its first quarter.","cn":"月亮正处于上弦。"}},{"en":"one of the four periods of time into which a game of American football is divided","cn":"（美式足球的）一节","g":"[countable]","sc":"in sport","ex":{"en":"Ford scored the winning touchdown early in the fourth quarter.","cn":"福特在第四局早早达阵，锁定胜局。"}},{"en":"a unit for measuring weight, a quarter of a pound; 4 ounces","cn":"夸特（重量单位，¼ 磅；4 盎司）","g":"[countable]","lab":"British English","sc":"weight"},{"en":"a unit for measuring weight, 28 pounds in the UK or 25 pounds in the US; a quarter of a hundredweight","cn":"夸特（重量单位，英国为 28 磅，美国为 25 磅；四分之一英担）","g":"[countable]","sc":"weight"},{"en":"kind treatment of an enemy or opponent who is in your power","cn":"（对掌控中的敌人或对手的）慈悲，同情","g":"[uncountable]","lab":"literary","sc":"pity","ex":{"en":"His rivals knew that they could expect no quarter from such a ruthless adversary.","cn":"他的竞争者明白，不能期望如此残忍的对手发善心。"}},{"en":"to cut or divide something into four parts","cn":"把…切成（或分成）四部分","sc":"divide into 4","ex":{"en":"She peeled and quartered an apple.","cn":"她削去苹果皮，把苹果切成四瓣。"},"pos":"verb"},{"en":"to provide somebody with a place to eat and sleep","cn":"给…提供食宿","lab":"formal","sc":"provide rooms","ex":{"en":"The soldiers were quartered in the town.","cn":"士兵在镇里宿营。"},"pos":"verb"}]},"collins":{"senses":[{"pos":"FRACTION 分数词","cn":"四分之一","en":"A quarter is one of four equal parts of something.","ex":{"en":"A quarter of the residents are over 55 years old","cn":"1/4的居民年龄在55岁以上。"}},{"pos":"N-COUNT 可数名词","cn":"季度;季","en":"A quarter is a fixed period of three months. Companies often divide their financial year into four quarters.","ex":{"en":"The group said results for the third quarter are due on October 29.","cn":"该集团表示第三季度的结果将于10月29日公布。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"一刻钟；十五分钟","en":"When you are telling the time, you use quarter to talk about the fifteen minutes before or after an hour. For example, 8.15 is quarter past eight, and 8.45 is quarter to nine. In American English, you can also say that 8.15 is a quarter after eight and 8.45 is a quarter of nine.","ex":{"en":"It was a quarter to six","cn":"当时是6点差一刻。"}},{"pos":"VERB 动词","cn":"把…分成四等份","en":"If you quarter something such as a fruit or a vegetable, you cut it into four roughly equal parts.","ex":{"en":"Chop the mushrooms and quarter the tomatoes.","cn":"把蘑菇切成丁，再把西红柿切成四瓣。"}},{"pos":"VERB 动词","cn":"把…降至原先的四分之一;把…减少四分之三","en":"If the number or size of something is quartered, it is reduced to about a quarter of its previous number or size.","ex":{"en":"The doses I suggested for adults could be halved or quartered.","cn":"我之前建议成人服用的剂量可以降到1/2或者1/4。"}},{"pos":"N-COUNT 可数名词","cn":"(美国或加拿大的)25分硬币","en":"A quarter is an American or Canadian coin that is worth 25 cents.","ex":{"en":"I dropped a quarter into the slot of the pay phone.","cn":"我向付费电话的投币孔里投了一枚25分硬币。"}},{"pos":"N-COUNT 可数名词","cn":"(城镇中某一类人群生活或工作的)区，地区","en":"A particular quarter of a town is a part of the town where a particular group of people traditionally live or work.","ex":{"en":"Look for hotels in the French Quarter.","cn":"在法国人居住区寻找旅馆。"}},{"pos":"N-COUNT 可数名词","cn":"(做出反应或行动的)某位人士，某个团体","en":"To refer to a person or group you may not want to name, you can talk about the reactions or actions from a particular quarter .","ex":{"en":"Help came from an unexpected quarter","cn":"援助来自于一个意想不到的团体。"}},{"pos":"N-PLURAL 复数名词","cn":"(军人、水手、仆人的)住处，宿舍，营房","en":"The rooms provided for soldiers, sailors, or servants to live in are called their quarters .","ex":{"en":"Mckinnon went down from deck to the officers' quarters.","cn":"麦金农走下甲板，来到军官们的住处。"}},{"pos":"VERB 动词","cn":"为…提供临时住所","en":"If people are quartered somewhere, they are provided with accommodation for a short time, usually while they are working away from home.","ex":{"en":"Our soldiers are quartered in Peredelkino.","cn":"我们的士兵在佩列杰利基诺扎营。"}},{"pos":"PHRASE 短语","cn":"近距离地;近在咫尺；接近地","en":"If you do something at close quarters, you do it very near to a particular person or thing.","ex":{"en":"You can watch aircraft take off or land at close quarters","cn":"你可以近距离观察飞机的起降。"}},{"pos":"PHRASE 短语","cn":"不仁慈；不宽恕","en":"If you say that someone was given no quarter, you mean that they were not treated kindly by someone who had power or control over them.","ex":{"en":"This is not war as you learned it. It is brutal work, with no quarter given.","cn":"这并不是你所了解的战争。它残酷无情，对人没有半点怜悯。"}}]},"examples":[{"en":"( NAmE also ) It's quarter of four now — I'll meet you at quarter after.","cn":"现在是三点四十五分，我将在四点十五分和你碰面。"},{"en":"His rivals knew that they could expect no quarter from such a ruthless adversary.","cn":"他的竞争者明白，不能期望如此残忍的对手发善心。"}]},"quote":{"oxford":{"phon":"kwəʊt","pos":"verb","senses":[{"en":"to repeat the exact words that another person has said or written","cn":"引用；引述","g":"[transitive, intransitive]","sc":"repeat exact words","ex":{"en":"to quote Shakespeare","cn":"引用莎士比亚的话"}},{"en":"to mention an example of something to support what you are saying","cn":"举例说明","g":"[transitive]","sc":"give example","ex":{"en":"Can you quote me an instance of when this happened?","cn":"你能否给我举例说明一下这事发生的时间？"}},{"en":"to tell a customer how much money you will charge them for a job, service or product","cn":"开价；出价；报价","g":"[transitive, intransitive]","sc":"give price","ex":{"en":"The agent is quoting a guide price of €250 000.","cn":"代理商给出的指导价为250 000欧元。"}},{"en":"to give a market price for shares, gold or foreign money","cn":"为（股票、黄金或外汇）报价","g":"[transitive]","lab":"finance","sc":"give price","ex":{"en":"Yesterday the pound was quoted at $1.8285, unchanged from Monday.","cn":"昨天英镑报价为 1.8285 美元，这个价格从星期一以来未变。"}},{"en":"to give the prices for a business company’s shares on a stock exchange","cn":"为（企业的股份）上市，挂牌","g":"[transitive]","lab":"finance","sc":"give price","ex":{"en":"Several football clubs are now quoted on the Stock Exchange.","cn":"目前有几家足球俱乐部在股票交易所上市。"}},{"en":"a group of words or a short piece of writing taken from a book, play, speech, etc. and repeated because it is interesting or useful","cn":"引语；引文；语录","lab":"rather formal","sc":"exact words","ex":{"en":"The essay was full of quotes.","cn":"这篇文章满篇皆是引语。"},"pos":"noun"},{"en":"a statement of how much money a particular piece of work will cost","cn":"报价；估价","lab":"rather formal","sc":"price","ex":{"en":"Their quote for the job was way too high.","cn":"他们给这项工作开价太高了。"},"pos":"noun"},{"en":"a pair of marks (‘ ’) or ( “ ” ) placed around a word, sentence, etc. to show that it is what somebody said or wrote, that it is a title or that you are using it in an unusual way","cn":"引号","g":"[plural]","lab":"more formal","sc":"punctuation","ex":{"en":"If you take text from other sources, place it in quotes.","cn":"引用其他来源的资料要放在引号里。"},"pos":"noun"}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"引述;引用","en":"If you quote someone as saying something, you repeat what they have written or said.","ex":{"en":"He quoted Mr Polay as saying that peace negotiations were already underway","cn":"他引用波利先生的话，说和谈已在进行之中。"}},{"pos":"N-COUNT 可数名词","cn":"引文；引语；语录","en":"A quote from a book, poem, play, or speech is a passage or phrase from it.","ex":{"en":"The article starts with a quote from an unnamed member of the Cabinet.","cn":"文章的开头引用了一位未透露姓名的内阁成员说过的话。"}},{"pos":"VERB 动词","cn":"援引，引用(法律条款、事实等)","en":"If you quote something such as a law or a fact, you state it because it supports what you are saying.","ex":{"en":"Mr Meacher quoted statistics saying that the standard of living of the poorest people had fallen.","cn":"米彻先生援引统计数据来说明最贫困人口的生活水平下降了。"}},{"pos":"VERB 动词","cn":"报(价);开(价)","en":"If someone quotes a price for doing something, they say how much money they would charge you for a service they are offering or for a job that you want them to do.","ex":{"en":"A travel agent quoted her £160 for a flight from Bristol to Palma","cn":"一位旅行社职员给她开出的从布里斯托尔至帕尔马的机票报价是160英镑。"}},{"pos":"N-COUNT 可数名词","cn":"报价;开价","en":"A quote for a piece of work is the price that someone says they will charge you to do the work.","ex":{"en":"Always get a written quote for any repairs needed.","cn":"每次进行修理都索要一份书面的报价单。"}},{"pos":"V-PASSIVE 被动动词","cn":"报…的牌价;为…报价","en":"If a company's shares, a substance, or a currency is quoted at a particular price, that is its current market price.","ex":{"en":"In early trading in Hong Kong yesterday, gold was quoted at $368.20 an ounce","cn":"在香港昨天早些时候的交易中，黄金的牌价为每盎司368.20美元。"}},{"pos":"N-PLURAL 复数名词","cn":"同 quotation mark","en":"Quotes are the same as quotation marks .","ex":{"en":"The word 'remembered' is in quotes.","cn":"remembered 一词用引号括了起来。"}},{"pos":"CONVENTION 惯用语","cn":"原话是;这是…的原话","en":"You can say 'quote' to show that you are about to quote someone's words.","ex":{"en":"He predicts they will have, quote, 'an awful lot of explaining to do'.","cn":"他预计他们需要“大费周章地解释一番”，这是他的原话。"}}]},"media":{"uk":"media/uk/quote__gb_1.mp3","us":"media/us/quote__us_1.mp3"},"examples":[{"en":"It was quote, ‘the hardest decision of my life’, unquote, and one that he lived to regret.","cn":"那是，原话起，“我一生最难作出的决定”，原话止，而且是他终生悔恨的决定。"},{"en":"Yesterday the pound was quoted at $1.8285, unchanged from Monday.","cn":"昨天英镑报价为 1.8285 美元，这个价格从星期一以来未变。"}]},"quest":{"oxford":{"phon":"kwest","pos":"noun","senses":[{"en":"a long search for something, especially for some quality such as happiness","cn":"探索，寻找，追求（幸福等）","ex":{"en":"the quest for happiness/knowledge/truth","cn":"对幸福／知识／真理的追求"}},{"en":"to search for something that is difficult to find","cn":"探索；探求","pos":"verb"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"(长期艰难的)追求，探索，寻找","en":"A quest is a long and difficult search for something.","ex":{"en":"My quest for a better bank continues.","cn":"我继续寻找一家更好的银行。"}}]},"media":{"uk":"media/uk/quest__gb_1.mp3","us":"media/us/quest__us_1.mp3"},"examples":[{"en":"He set off in quest of adventure.","cn":"他出行探险去了。"},{"en":"the quest for happiness/knowledge/truth","cn":"对幸福/知识/真理的追求"}]},"quartet":{"media":{"uk":"media/uk/quartet__gb_1.mp3","us":"media/us/quartet__us_1.mp3"},"oxford":{"phon":"kwɔːˈtet","pos":"noun","senses":[{"en":"a group of four musicians or singers who play or sing together","cn":"四重奏乐队；四重唱组合","g":"[countable + singular or plural verb]","ex":{"en":"the Amadeus Quartet","cn":"阿玛迪厄斯四重奏乐队"}},{"en":"a piece of music for four musicians or singers","cn":"四重奏（曲）；四重唱（曲）","g":"[countable]","ex":{"en":"a Beethoven string quartet","cn":"贝多芬弦乐四重奏曲"}},{"en":"a set of four people or things","cn":"四人组；四件套；四部曲","g":"[countable + singular or plural verb]","ex":{"en":"the last in a quartet of novels","cn":"四部曲小说的最后一部"}}]},"collins":{"senses":[{"pos":"N-COUNT-COLL 可数集合名词","cn":"四重奏乐团;四重唱组合","en":"A quartet is a group of four people who play musical instruments or sing together.","ex":{"en":"...a string quartet.","cn":"四重奏弦乐团"}},{"pos":"N-COUNT 可数名词","cn":"四重奏曲;四重唱曲","en":"A quartet is a piece of music for four instruments or four singers."},{"pos":"N-COUNT 可数名词","cn":"四人组;四件套；四个一组","en":"A quartet of people or things is a group or set of four people or things.","ex":{"en":"...a quartet of books.","cn":"一套4本的书"}}]},"examples":[{"en":"the last in a quartet of novels","cn":"四部曲小说的最后一部"},{"en":"the Amadeus Quartet","cn":"阿玛迪厄斯四重奏乐队"}]},"qualities":{"lemma":"quality"},"quickened":{"oxford":{"phon":"ˈkwɪkən","pos":"verb","senses":[{"en":"to become quicker or make sth quicker （","cn":"使）加快，加速"},{"en":"to become more active; to make sth more active","cn":"变得更活跃；使更活跃"}]}},"questioned":{"lemma":"question"},"queuing":{"lemma":"queue"},"questions":{"lemma":"question"},"quotas":{"lemma":"quota"},"quarters":{"lemma":"quarter"},"queens":{"oxford":{"phon":"kwiːnz","pos":"","senses":[{"en":"the largest of the five boroughs of New York City. It has a border with Long Island. It was named after the wife of Charles II. The area of Queens called Astoria is known for its large Greek community. The John F Kennedy Airport, several racing tracks and the Museum of the Moving Image are all in Queens.","cn":"皇后区：纽约市五个行政区中最大的行政区。它与长岛接壤。它以查理二世的妻子的名字命名。皇后区称为阿斯托里亚（Astoria），以其庞大的希腊社区而闻名。约翰·肯尼迪机场，数条赛道和运动图像博物馆都位于皇后区。"}]},"media":{"uk":"media/ldoce/hwd/bre/f/p028-000010165.mp3","us":"media/ldoce/hwd/ame/f/p028-000010165.mp3"},"base":"queen"},"quicker":{"lemma":"quick"},"quarrelling":{"lemma":"quarrel"},"questionable":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"可疑的;不可靠的;有问题的;不确定的","en":"If you say that something is questionable, you mean that it is not completely honest, reasonable, or acceptable.","ex":{"en":"He has been dogged by allegations of questionable business practices","cn":"他一直被那些指控他有不正当商业行为的说法所困扰。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"use this about behaviour or a situation that makes you think that someone is doing something dishonest","cn":""},{"en":"use this to describe business deals or the people involved in them, when they seem dishonest or illegal, especially because the business is secret","cn":""},{"en":"someone who is shifty looks or behaves as if they are doing or planning something dishonest","cn":""}]},"vocab":{"pos":"adj","senses":[{"en":"Something that's questionable is uncertain or hard to believe. If a politician says things you doubt are true, you might describe his words as questionable ."}]},"collocations":{"phrases":["VERBS be | become | remain","ADV. highly, very Their motives for undertaking this study are highly questionable. | rather, somewhat"]},"media":{"uk":"media/ldoce/hwd/bre/3/questionable0205.mp3","us":"media/ldoce/hwd/ame/b/questionable.mp3"},"examples":[{"en":"It is questionable whether this is a good way of solving the problem.","cn":"这未必是一个解决问题的好办法。"},{"en":"The conclusions that they come to are highly questionable.","cn":"他们得出的结论大有问题。"}],"oxford":{"phon":"ˈkwestʃənəbl","pos":"adjective","senses":[{"en":"that you have doubts about because you think it is not accurate or correct","cn":"可疑的；有问题的；未必准确（或正确）的","ex":{"en":"The conclusions that they come to are highly questionable.","cn":"他们得出的结论大有问题。"}},{"en":"likely to be dishonest or morally wrong","cn":"可能不诚实（或不道德）的；别有用心的","ex":{"en":"Her motives for helping are questionable.","cn":"她帮忙的动机令人生疑。"}}]}},"quirk":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"(偶然发生的)奇事，趣事","en":"A quirk is something unusual or interesting that happens by chance.","ex":{"en":"By a tantalising quirk of fate, the pair have been drawn to meet in the first round of the championship","cn":"仿佛是命运的捉弄，这对选手在锦标赛第一轮比赛中就狭路相逢。"}},{"pos":"N-COUNT 可数名词","cn":"怪癖;古怪的性格","en":"A quirk is a habit or aspect of a person's character which is odd or unusual.","ex":{"en":"Brown was fascinated by people's quirks and foibles.","cn":"布朗对人们的种种怪癖十分着迷。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"something such as an ability or a way of behaving that is part of someone's character","cn":""},{"en":"a part of someone's character, especially a part that is thought by other people to be good and useful","cn":""},{"en":"someone's characteristics are the qualities that are typical of them and which make them easy to recognize","cn":""}]},"vocab":{"pos":"1 n 2 v 3 n","senses":[{"en":"A quirk is a unique, odd, and sometimes charming trait that makes a person stand out from the crowd. Country comedian Minnie Pearl was known for her quirk of wearing a $1.98 price tag dangling from her hat."}]},"collocations":{"phrases":["ADJ. curious, odd, peculiar, strange | little","VERB + QUIRK have The system has some odd little quirks.","PREP. by a ~ of By a strange quirk of fate, she later married the first boyfriend she'd ever had. | ~ in as a result of some quirk in the so","PHRASES a quirk of fate"]},"media":{"uk":"media/ldoce/hwd/bre/a/quirk0205.mp3","us":"media/ldoce/hwd/ame/7/quirk.mp3"},"examples":[{"en":"David quirked an eyebrow and smirked slightly.","cn":"戴维突然扬了扬眉毛，轻轻地傻笑了一下。"},{"en":"By a strange quirk of fate they had booked into the same hotel.","cn":"真是天缘奇遇，他们住进了同一家旅馆。"}],"oxford":{"phon":"kwɜːk","pos":"noun","senses":[{"en":"an aspect of somebody’s personality or behaviour that is a little strange","cn":"怪异的性格（或行为）；怪癖","ex":{"en":"Everyone has their own little quirks and mannerisms.","cn":"每个人都有自己的小怪癖和习惯。"}},{"en":"a strange thing that happens, especially by accident","cn":"（尤指偶发的）怪事，奇事","ex":{"en":"By a strange quirk of fate they had booked into the same hotel.","cn":"真是天缘奇遇，他们住进了同一家旅馆。"}},{"en":"to twist your mouth or eyebrows suddenly; (of your mouth or eyebrows) to move in this way","cn":"突然扭曲（嘴或眉毛）；撇嘴；扬眉；皱眉","ex":{"en":"David quirked an eyebrow and smirked slightly.","cn":"戴维突然扬了扬眉毛，露出一丝自鸣得意的笑。"},"pos":"verb"}]}},"quarrel":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"争吵；吵架；拌嘴","en":"A quarrel is an angry argument between two or more friends or family members.","ex":{"en":"I had a terrible quarrel with my other brothers","cn":"我跟其他几个兄弟大吵了一架。"}},{"pos":"N-COUNT 可数名词","cn":"不和;争端;争执","en":"Quarrels between countries or groups of people are disagreements, which may be diplomatic or include fighting.","ex":{"en":"...New Zealand's quarrel with France over the Rainbow Warrior incident","cn":"新西兰和法国关于“彩虹勇士号”事件的争端"}},{"pos":"V-RECIP 相互动词","cn":"争吵;吵架;吵嘴","en":"When two or more people quarrel, they have an angry argument.","ex":{"en":"At one point we quarrelled, over something silly","cn":"我们一度为一件愚蠢的小事吵了起来。"}},{"pos":"N-SING 单数名词","cn":"不满;不同意见","en":"If you say that you have no quarrel with someone or something, you mean that you do not disagree with them.","ex":{"en":"We have no quarrel with the people of Spain or of any other country","cn":"我们和西班牙以及其他国家的人民并无分歧。"}},{"pos":"VERB 动词","cn":"不同意;反对","en":"If you say that you would quarrel with someone or with something that they have said, you mean that you disagree with them.","ex":{"en":"I would quarrel with you on that figure","cn":"在那个数字的问题上，我并不认同你的看法。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a situation in which people speak angrily to each other because they disagree about something","cn":""},{"en":"a loud angry argument with someone, especially your boyfriend, girlfriend, or someone in your family. Row is also used about a serious disagreement between politicians about important public issues","cn":""},{"en":"a situation in which people disagree with each other, but without shouting or getting angry","cn":""}]},"vocab":{"pos":"1 n v 2 n","senses":[{"en":"To quarrel is to fight — but usually not physically. Quarreling is a fact of life, occurring between the best of friends, in the happiest of marriages, and between parents and their children."}]},"collocations":{"phrases":["ADV. bitterly, fiercely, violently","PREP. about, over What did you two quarrel about? | with He wished he hadn't quarrelled with Tania."]},"media":{"uk":"media/ldoce/hwd/bre/3/quarrel_n0205.mp3","us":"media/ldoce/hwd/ame/9/quarrel1.mp3"},"examples":[{"en":"She quarrelled with her brother over their father's will.","cn":"她和弟弟因父亲遗嘱的事起了争执。"},{"en":"We have no quarrel with his methods.","cn":"我们没有理由不赞成他的方法。"}],"oxford":{"phon":"ˈkwɒrəl","pos":"noun","senses":[{"en":"an angry argument or disagreement between people, often about a personal matter","cn":"口角；争吵；拌嘴","g":"[countable]","ex":{"en":"a family quarrel","cn":"家庭纷争"}},{"en":"a reason for complaining about somebody/something or for disagreeing with somebody/something","cn":"抱怨（或不赞成）的理由","g":"[uncountable]","ex":{"en":"We have no quarrel with his methods.","cn":"我们没有理由不赞成他的方法。"}},{"en":"to have an angry argument or disagreement","cn":"争吵；吵嘴；吵架","ex":{"en":"My sister and I used to quarrel all the time.","cn":"我和妹妹过去老是吵架。"},"pos":"verb"}]}},"query":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"（尤指向组织、出版物或专家提出的）问题，疑问，询问","en":"A query is a question, especially one that you ask an organization, publication, or expert.","ex":{"en":"If you have any queries about this insurance, please contact Travel Insurance Services Limited.","cn":"如果您对此项保险有什么疑问，请与旅行保险服务有限公司联系。"}},{"pos":"VERB 动词","cn":"对…提出疑问;对…表示怀疑","en":"If you query something, you check it by asking about it because you are not sure if it is correct.","ex":{"en":"It's got a number you can ring to query your bill","cn":"这上面有一个号码，您可以打电话查询您的账单。"}},{"pos":"VERB 动词","cn":"提问;发问;询问","en":"To query means to ask a question.","ex":{"en":"'Is there something else?' Ryle queried as Helen stopped speaking","cn":"海伦的话音刚落，赖尔便问道：“还有其他事吗？”"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"something that you ask someone, either when speaking or when writing","cn":""},{"en":"a question that you ask when you are not sure you have understood something or that the information you have is correct","cn":""},{"en":"a question you ask in order to get information or find out the details about something","cn":""}]},"vocab":{"pos":"n v","senses":[{"en":"A query is a question, or the search for a piece of information."}]},"collocations":{"phrases":["VERB + QUERY have If you have any queries regarding this offer, simply call our helpline. | raise | send in, write in with | put I've a quer","PREP. ~ about/as to/concerning/on/regarding/relating to Have you any queries about what you're supposed to do? We regret that we cannot deal"]},"media":{"uk":"media/ldoce/hwd/bre/f/query_n0205.mp3","us":"media/ldoce/hwd/ame/7/query1.mp3"},"examples":[{"en":"Put a query against Jack's name — I'm not sure if he's coming.","cn":"在杰克的名字旁边打个问号，我不确定他是否会来。"},{"en":"We queried the bill as it seemed far too high.","cn":"账单上的费用似乎太高了，我们对此表示怀疑。"}],"oxford":{"phon":"ˈkwɪəri","pos":"noun","senses":[{"en":"a question, especially one asking for information or expressing a doubt about something","cn":"疑问；询问","ex":{"en":"Our assistants will be happy to answer your queries.","cn":"我们的助理很乐意回答诸位的问题。"}},{"en":"a question mark to show that something has not been finished or decided","cn":"问号","ex":{"en":"Put a query against Jack's name—I'm not sure if he's coming.","cn":"在杰克的名字旁边打个问号，我不确定他是否会来。"}},{"en":"to express doubt about whether something is correct or not or what something means","cn":"怀疑；质疑","ex":{"en":"We queried the bill as it seemed far too high.","cn":"账单上的费用似乎太高了，我们对此表示怀疑。"},"pos":"verb"},{"en":"to ask a question; to put a question to somebody","cn":"提问；询问","lab":"especially North American English","ex":{"en":"‘Who will be leading the team?’ queried Simon.","cn":"“由谁当队长呢？”西蒙问道。"},"pos":"verb"}]}},"qualify":{"collins":{"senses":[{"pos":"VERB 动词","cn":"(通过考试)取得资格，合格，达到标准","en":"When someone qualifies, they pass the examinations that they need to be able to work in a particular profession.","ex":{"en":"But when I'd qualified and started teaching it was a different story","cn":"可是等我获得资格开始教书的时候，却是另一番情形了。"}},{"pos":"V-ERG 及物/不及物动词","cn":"(使)有资格获得;(使)有权去做","en":"If you qualify for something or if something qualifies you for it, you have the right to do it or have it.","ex":{"en":"To qualify for maternity leave you must have worked for the same employer for two years","cn":"你必须为同一个雇主工作满两年才能享受产假。"}},{"pos":"V-ERG 及物/不及物动词","cn":"可称得上;符合；可算作","en":"To qualify as something or to be qualified as something means to have all the features that are needed to be that thing.","ex":{"en":"13 percent of American households qualify as poor, says Mr. Mishel","cn":"米歇尔先生说，13%的美国家庭符合贫困家庭的标准。"}},{"pos":"VERB 动词","cn":"通过预赛;取得(下一轮)比赛资格","en":"If you qualify in a competition, you are successful in one part of it and go on to the next stage.","ex":{"en":"Nottingham Forest qualified for the final by beating Tranmere on Tuesday","cn":"诺丁汉森林队于星期二打败了特兰米尔队，取得了决赛资格。"}},{"pos":"VERB 动词","cn":"具体说明;使语气缓和","en":"If you qualify a statement, you make it less strong or less general by adding a detail or explanation to it.","ex":{"en":"I would qualify that by putting it into context.","cn":"我会将它放入上下文中进行具体解释。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to reach a high enough standard to succeed in an examination or test","cn":""},{"en":"to pass all the examinations that you need in order to become a doctor, lawyer, engineer etc","cn":""},{"en":"to pass all your final examinations at university or college, and get a degree. In the US, graduate also means to successfully complete your high school education","cn":""}]},"vocab":{"pos":"1 v 2 v","senses":[{"en":"Make sure you know the context when using the word qualify . In one sense, it means to be right for, to measure up. In another sense, though, qualify means to change something slightly, to limit it or add a condition to it."}]},"collocations":{"phrases":["ADV. automatically","PREP. for You will automatically qualify for a pension.","PHRASES qualify on the grounds of sth people who qualify for the grant on the grounds of disability 2 for a sports competition","ADV. easily | duly South Korea duly qualified for the finals when they beat Italy 6?1.","VERB + QUALIFY fail to","PREP. for England failed to qualify for the final. 3 fit a description","ADV. hardly","PREP. as A three-week course hardly qualifies as sufficient training."]},"media":{"uk":"media/ldoce/hwd/bre/9/qualify0205.mp3","us":"media/ldoce/hwd/ame/d/qualify.mp3"},"examples":[{"en":"In ‘the open door’, ‘open’ is an adjective qualifying ‘door’.","cn":"在 the open door 中，open 是修饰 door 的形容词。"},{"en":"I want to qualify what I said earlier — I didn't mean he couldn't do the job, only that he would need supervision.","cn":"我想具体说明一下我原先的话，我没有说他不能担任这工作，只是说他需要指导。"}],"oxford":{"phon":"ˈkwɒlɪfaɪ","pos":"verb","senses":[{"en":"to reach the standard of ability or knowledge needed to do a particular job, for example by completing a course of study or passing exams","cn":"取得资格（或学历）；合格","g":"[intransitive]","sc":"for job","ex":{"en":"How long does it take to qualify?","cn":"需要多长时间才能取得资格？"}},{"en":"to give somebody the skills and knowledge they need to do something","cn":"使合格；使具备资格","g":"[transitive]","sc":"give skills/knowledge","ex":{"en":"This training course will qualify you for a better job.","cn":"本培训课程将使你能胜任更好的工作。"}},{"en":"to be of a high enough standard to enter a competition; to defeat another person or team in order to enter or continue in a competition","cn":"达标；获得参赛资格","g":"[intransitive]","sc":"for competition","ex":{"en":"He failed to qualify.","cn":"他未能获得参赛资格。"}},{"en":"to have or give somebody the right to do something","cn":"有权，使有权（做某事）","g":"[intransitive, transitive]","sc":"have/give right","ex":{"en":"To qualify, you must have lived in this country for at least three years.","cn":"你必须在这个国家居住至少三年才能享有此权利。"}},{"en":"to have the right qualities to be described as a particular thing","cn":"符合，配得上（某称号、名称等）","g":"[intransitive, transitive]","sc":"fit description","ex":{"en":"Do you think this dress qualifies as evening wear?","cn":"你看这连衣裙适合作晚礼服吗？"}},{"en":"to add something to a previous statement to make the meaning less strong or less general","cn":"使所说的话语气减弱（或更具体等）","g":"[transitive]","sc":"statement","ex":{"en":"I want to qualify what I said earlier—I didn't mean he couldn't do the job, only that he would need supervision.","cn":"我想具体说明一下我原先的话，我没有说他不能胜任这工作，只是说他需要指导。"}},{"en":"to describe another word in a particular way","cn":"修饰；限定","g":"[transitive]","sc":"grammar","ex":{"en":"In ‘the open door’, ‘open’ is an adjective qualifying ‘door’.","cn":"在 the open door 中，open 是修饰 door 的形容词。"}}]}},"quota":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"定量;定额;配额","en":"A quota is the limited number or quantity of something which is officially allowed.","ex":{"en":"The quota of four tickets per person had been reduced to two.","cn":"每人可购买的票的限额已经由四张降至两张。"}},{"pos":"N-COUNT 可数名词","cn":"(给予某团体的)限额，配额","en":"A quota is a fixed maximum or minimum proportion of people from a particular group who are allowed to do something, such as come and live in a country or work for the government.","ex":{"en":"The bill would force employers to adopt a quota system when recruiting workers.","cn":"该法案将迫使雇主在招聘工人时采取限额制度。"}},{"pos":"N-COUNT 可数名词","cn":"配额;份额;指标","en":"Someone's quota of something is their expected or deserved share of it.","ex":{"en":"They have the usual quota of human weaknesses, no doubt.","cn":"毫无疑问，他们身上也有人所共有的弱点。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"how much of something there is","cn":""},{"en":"a particular amount of food, liquid, or another substance that can be measured – used especially in written descriptions and instructions","cn":""},{"en":"the amount of something such as business activity or traffic, especially when this is large or increasing","cn":""}]},"vocab":{"pos":"n","senses":[{"en":"A quota is a specific number of things. If a quota is placed on the total number of apples each visitor can pick at an orchard, it means that once you've picked a certain number of apples, you have to stop."}]},"collocations":{"phrases":["ADJ. full He never takes his full quota of holidays. | annual, daily, monthly, weekly | national | fishing, milk, etc. the introduction of E","VERB + QUOTA agree, determine, establish, set | allocate, impose, introduce | increase | reduce | achieve, fill, fulfil, reach We had to inc","QUOTA + NOUN system","PREP. ~ for quotas for oil production | ~ on national quotas on imports of cars"]},"media":{"uk":"media/ldoce/hwd/bre/d/quota0205.mp3","us":"media/ldoce/hwd/ame/e/quota.mp3"},"examples":[{"en":"I'm going home now — I've done my quota of work for the day.","cn":"我现在要回家了。我已完成了今天的工作量。"},{"en":"He was 76 votes short of the quota.","cn":"他比规定当选票数少了 76 票。"}],"oxford":{"phon":"ˈkwəʊtə","pos":"noun","senses":[{"en":"a limited number or amount of people or things that is officially allowed","cn":"定额；限额；配额","g":"[countable]","ex":{"en":"to introduce a strict import quota on grain","cn":"严格限制谷物进口量"}},{"en":"an amount of something that somebody expects or needs to have or achieve","cn":"定量；定额；指标","g":"[countable]","ex":{"en":"I'm going home now—I've done my quota of work for the day.","cn":"我现在要回家了。我已完成了今天的工作量。"}},{"en":"a fixed number of votes that a candidate needs in order to be elected","cn":"（候选人当选所需的）规定票数，最低票数","g":"[singular]","lab":"politics","ex":{"en":"He was 76 votes short of the quota.","cn":"他比规定当选票数少了 76 票。"}}]}},"questionnaire":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"调查问卷;调查表","en":"A questionnaire is a written list of questions which are answered by a lot of people in order to provide information for a report or a survey.","ex":{"en":"Headteachers will be asked to fill in a questionnaire.","cn":"校长们将被要求完成一份问卷调查。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a piece of paper with a set of questions on it, which is given to a large number of people to find out what they think","cn":""},{"en":"a piece of paper with a set of questions that you answer in order to provide information about yourself for an organization, employer etc","cn":""},{"en":"a written set of questions which you give to a large number of people in order to collect information 〔","cn":"用以收集资料的〕问卷﹐调查表"}]},"vocab":{"pos":"n","senses":[{"en":"A questionnaire is a form containing a set of questions. After the opening night of your new restaurant, ask your customers to fill out a questionnaire so they can help you know what still needs work."}]},"collocations":{"phrases":["ADJ. short, simple | detailed, lengthy | postal","VERB + QUESTIONNAIRE design, draw up, prepare | circulate, distribute, send (out) | receive | complete, fill in/out | reply to, respond to, ","PREP. ~ about Local companies were asked to complete a questionnaire about their exports. | ~ concerning questionnaires concerning people's "]},"media":{"uk":"media/ldoce/hwd/bre/7/questionnaire0205.mp3","us":"media/ldoce/hwd/ame/3/questionnaire.mp3"},"examples":[{"en":"( BrE ) to fill in a questionnaire","cn":"填调查表"},{"en":"( especially NAmE ) to fill out a questionnaire","cn":"填调查表"}],"oxford":{"phon":"ˌkwestʃəˈneə(r)","pos":"noun","senses":[{"en":"a written list of questions that are answered by a number of people so that information can be collected from the answers","cn":"调查表；问卷","lab":"British English","ex":{"en":"to fill in a questionnaire","cn":"填调查表"}}]}},"quarantine":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"检疫；隔离","en":"If a person or animal is in quarantine, they are being kept separate from other people or animals for a set period of time, usually because they have or may have a disease.","ex":{"en":"She was sent home to Oxford and put in quarantine","cn":"她被送回牛津的家中隔离起来。"}},{"pos":"VERB 动词","cn":"对…进行隔离检疫","en":"If people or animals are quarantined, they are stopped from having contact with other people or animals. If a place is quarantined, people and animals are prevented from entering or leaving it.","ex":{"en":"Dogs have to be quarantined for six months before they'll let them in.","cn":"狗要进行6个月的隔离检疫之后才被允许进入。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"to keep two or more people apart, especially so that they cannot cause any trouble together","cn":""},{"en":"to separate two or more people so that they cannot talk to or harm each other","cn":""},{"en":"to keep someone away from other people, especially because they are suffering from an infectious disease","cn":""}]},"vocab":{"pos":"n v","senses":[{"en":"If you contract something highly infectious, such as pinkeye, please quarantine yourself so that you don’t infect others with it. This means you’ll have to stay in isolation and avoid contact with other people."}]},"collocations":{"phrases":["ADJ. strict","VERB + QUARANTINE keep sb/sth in, put sb/sth in","QUARANTINE + NOUN period | regulations","PREP. in ~ The animals are still in quarantine at the port."]},"media":{"uk":"media/ldoce/hwd/bre/0/quarantine_n0205.mp3","us":"media/ldoce/hwd/ame/9/quarantine1.mp3"},"examples":[{"en":"The dog was kept in quarantine for six months.","cn":"这条狗被检疫隔离了六个月。"},{"en":"quarantine regulations","cn":"检疫的规定"}],"oxford":{"phon":"ˈkwɒrəntiːn","pos":"noun","senses":[{"en":"a period of time when an animal or a person that has or may have a disease is kept away from others in order to prevent the disease from spreading","cn":"（为防传染的）检疫，隔离期","ex":{"en":"The dog was kept in quarantine for six months.","cn":"这条狗被检疫隔离了六个月。"}},{"en":"to put an animal or a person into quarantine; to go into quarantine","cn":"（对动物或人）进行检疫，隔离；进入隔离期","ex":{"en":"Animals brought into the country are automatically quarantined.","cn":"入境的动物一律进行检疫。"},"pos":"verb"}]}},"quotation":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"引文;引语;语录","en":"A quotation is a sentence or phrase taken from a book, poem, or play, which is repeated by someone else.","ex":{"en":"He illustrated his argument with quotations from Pasternak","cn":"他引用帕斯捷尔纳克的话来证明自己的论点。"}},{"pos":"N-COUNT 可数名词","cn":"报价;开价","en":"When someone gives you a quotation, they tell you how much they will charge to do a particular piece of work.","ex":{"en":"Get several written quotations and check exactly what's included in the cost.","cn":"要几份书面报价，仔细查对费用中包含的内容。"}},{"pos":"N-COUNT 可数名词","cn":"(股票的)挂牌","en":"A company's quotation on the stock exchange is its registration on the stock exchange, which enables its shares to be officially listed and traded.","ex":{"en":"...an American-dominated investment manager with a quotation on the London stock market.","cn":"在伦敦股票交易市场挂牌的由美国人主导的投资管理机构"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"to calculate the total cost of a plan or process - used especially in business contexts","cn":""},{"en":"to decide how much a product should cost","cn":""},{"en":"a statement that says how much money it will probably cost to build or repair something","cn":""}]},"vocab":{"pos":"1 n 2 n","senses":[{"en":"A quotation is the exact words of someone else. When you like what someone said, put their quotation in your writing."}]},"collocations":{"phrases":["ADJ. famous, memorable | direct, verbatim a direct quotation from a recent speech by the prime minister | illustrative | biblical","VERB + QUOTATION take My quotation is taken from &lsquo;Hamlet&rsquo;.","QUOTATION + VERB come from sth Where does that quotation come from?","QUOTATION + NOUN dictionary","PREP. ~ from It's a quotation from a poem by Keats. 2 price that will be charged for a piece of work","ADJ. written | free | detailed","VERB + QUOTATION give (sb), provide (sb with), supply (sb with) Most builders will give you a free quotation. | get, obtain | accept","PREP. ~ for Always get several quotations for the job."]},"media":{"uk":"media/ldoce/hwd/bre/4/quotation0205.mp3","us":"media/ldoce/hwd/ame/5/quotation.mp3"},"examples":[{"en":"The book began with a quotation from Goethe.","cn":"这本书一开头引用了歌德的隽语。"},{"en":"The writer illustrates his point by quotation from a number of sources.","cn":"作者旁征博引以证明自己的观点。"}],"oxford":{"phon":"kwəʊˈteɪʃn","pos":"noun","senses":[{"en":"a group of words or a short piece of writing taken from a book, play, speech, etc. and repeated because it is interesting or useful","cn":"引语；引文；语录","g":"[countable]","lab":"rather formal","ex":{"en":"a dictionary of quotations","cn":"引语词典"}},{"en":"the act of repeating something interesting or useful that another person has written or said","cn":"引用；引述；引证","g":"[uncountable]","ex":{"en":"The writer illustrates his point by quotation from a number of sources.","cn":"作者旁征博引以阐明自己的观点。"}},{"en":"a statement of how much money a particular piece of work will cost","cn":"报价；估价","g":"[countable]","lab":"rather formal","ex":{"en":"You need to get a written quotation before they start work.","cn":"你得在他们开工之前拿到报价单。"}},{"en":"a statement of the current value of goods or shares","cn":"（货物或股票的）行情，市价，牌价","g":"[countable]","lab":"finance","ex":{"en":"the latest quotations from the Stock Exchange","cn":"股票交易所的最新行情"}}]}},"queensland":{"ldoce":{"phon":"hwd","pos":"","senses":[{"en":"a state in northeast Australia, whose capital and largest city is Brisbane. Its products include sugar, wool, and many types of mineral, including coal. Queensland is a popular place for tourists because of its warm weather, its beaches on the Gold Coast, and ","cn":""}]},"media":{"uk":"media/ldoce/hwd/bre/f/p028-000010171.mp3","us":"media/ldoce/hwd/ame/f/p028-000010171.mp3"},"oxford":{"phon":"ˈkwiːnzlənd","pos":"","senses":[{"en":"a state covering the north-eastern part of Australia. The capital is Brisbane.","cn":"昆士兰（包含澳大利亚东北部的州，首府布里斯班）"}]}},"quintessential":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"典范的;典型的","en":"Quintessential means representing a perfect or typical example of something.","ex":{"en":"This was quintessential Midwestern farming country","cn":"这就是典型的中西部农村。"}},{"pos":"ADJ 形容词","cn":"本质的;精髓的","en":"Quintessential means representing the central nature of something.","ex":{"en":"...the quintessential charm of his songs.","cn":"他的歌声中最本质的魅力"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"a typical person or thing is a good example of that type of person or thing","cn":""},{"en":"used to describe a very typical and very good example of something","cn":""},{"en":"the archetypal person or thing is the most typical example of that kind of person or thing, and has all their most important qualities","cn":""}]},"vocab":{"pos":"adj","senses":[{"en":"If someone tells you you’re the quintessential rock musician, that means they think that everything about you screams “rock and roll.” Quintessential means embodying or possessing the essence of something."}]},"media":{"uk":"media/ldoce/hwd/bre/4/quintessential0205.mp3","us":"media/ldoce/hwd/ame/a/laadquintessential.mp3"},"examples":[{"en":"He was the quintessential tough guy.","cn":"他是个典型的硬汉子。"},{"en":"‘Guys and Dolls’ is the quintessential American musical. 《","cn":"少男少女》是典型的美国音乐剧。"}],"oxford":{"phon":"ˌkwɪntɪˈsenʃl","pos":"adjective","senses":[{"en":"representing the perfect example of something","cn":"典范的;典型的","ex":{"en":"He was the quintessential tough guy.","cn":"他是个典型的硬汉。"}}]}}});
